/*
 * EVERY ROW ABOUT ONE PERSON, BY ONE PLAN (TASK-L185 §3, §4).
 *
 * The plan below is the ONLY statement of which rows belong to a person.
 * `exportMine` hands them over and `deleteMine` removes them, and both read it
 * from here, so a collection cannot be exported and forgotten by the deletion,
 * or the other way round (the product's L55, delete.ts enumerating the schema).
 * tools/check-privacy.mjs parses PLAN and NOTHING_ABOUT_THEM out of this node
 * and fails on any collection in backend/schema.json that is in neither — a
 * collection added later is a failure until somebody decides about it.
 *
 * A row is found one of two ways:
 *   by  — a field on the row holds their learner id;
 *   via — the row hangs off another row in the plan (a step off a path).
 * A `via` row is collected from what is left of its parent, which is why
 * deletion removes children before parents: a crash between two collections
 * then leaves parents behind (still findable, so a second run finishes), never
 * children that nothing can find any more.
 *
 * WHAT IS NOT HERE AND WHY:
 * - A group's brief and a group's session (`learnerId` empty, a `cohortId`
 *   instead) name nobody and outlive one member (the product's L105, L116).
 *   Their ANSWERS to a group's brief are theirs, and are in the plan.
 * - Rows a coach's account wrote about SOMEBODY ELSE (a note, a session) belong
 *   to that other learner and stay with them, carrying the coach's address.
 * - The account itself (`_User`, its sessions, sign-in identities, email
 *   tokens and role memberships) is read and removed by the two functions that
 *   use this node, because it is keyed on the account rather than the learner,
 *   and a staff account has no learner at all.
 *
 * Reads are `{ plain: true }` (NodeGX HLT-022). A read that comes back full
 * (1000 rows) is REFUSED rather than trusted: handing over or deleting a
 * partial set while saying it was everything is the failure this exists for.
 */
const PLAN = [
  { c: 'ProjectContext', by: 'learnerId' },
  { c: 'LearningPath', by: 'learnerId' },
  { c: 'PathStep', via: 'LearningPath', key: 'pathId' },
  { c: 'Progress', by: 'learnerId' },
  { c: 'Lesson', by: 'learnerId' },
  { c: 'LessonDraft', by: 'learnerId' },
  { c: 'Signal', by: 'learnerId' },
  { c: 'ArtifactSubmission', by: 'learnerId' },
  { c: 'Assignment', by: 'learnerId' },
  { c: 'AssignmentSubmission', by: 'learnerId' },
  { c: 'CoachNote', by: 'learnerId' },
  { c: 'CoachingSession', by: 'learnerId' },
  { c: 'SessionPrep', via: 'CoachingSession', key: 'sessionId' },
  { c: 'Conversation', by: 'learnerId' },
  { c: 'ConversationMessage', via: 'Conversation', key: 'conversationId' },
  { c: 'Programme', by: 'learnerId' },
  { c: 'ProgrammeDimension', via: 'Programme', key: 'programmeId' },
  { c: 'ProgrammeEvaluation', via: 'Programme', key: 'programmeId' },
  { c: 'DimensionRating', via: 'ProgrammeDimension', key: 'dimensionId' },
  { c: 'LearnerDeliverable', by: 'learnerId' },
  { c: 'DeliverableConcept', via: 'LearnerDeliverable', key: 'deliverableId' },
  { c: 'CohortMember', by: 'learnerId' },
  { c: 'LearnerInvite', by: 'claimedByLearnerId' },
  { c: 'LearnerProfile', by: 'learnerId' }
];

const NOTHING_ABOUT_THEM = {
  Concept: "the course's list of topics: a title per topic, naming nobody",
  Cohort: "a group's name; a group outlives any one member, and their membership is CohortMember, in the plan"
};

/*
 * ROWS THAT GO WHEN THEY GO, BUT ARE NOT THEIRS TO TAKE AWAY (TASK-L189 §5).
 *
 * A lesson copied from this person's lesson to another learner (copyLesson)
 * lands as THAT learner's draft, carrying `copiedFromLearnerId`. Until a publish
 * passes the leak check and clears the pointer, it is still this person's words
 * about this person's project. So deletion removes it — and the export does NOT
 * hand it over, because it is the other learner's draft. tools/check-privacy.mjs
 * requires every collection here to be in PLAN as well.
 */
const ALSO_DELETED = [
  { c: 'LessonDraft', by: 'copiedFromLearnerId' }
];

/* Deletion order: a collection goes before anything it hangs off, and the
   learner profile goes last of all, because it is how a second run finds them. */
function deletionOrder() {
  const left = PLAN.filter((p) => p.c !== 'LearnerProfile').map((p) => p.c);
  const order = [];
  while (left.length) {
    const i = left.findIndex((c) => !left.some((o) => PLAN.find((p) => p.c === o).via === c));
    if (i === -1) throw new Error('the plan has a cycle');
    order.push(left.splice(i, 1)[0]);
  }
  order.push('LearnerProfile');
  return order;
}

if (Inputs.learnerId !== undefined) {
  (async () => {
    try {
      const learnerId = String(Inputs.learnerId || '');
      const rows = {};
      if (learnerId) {
        const q = async (c, where) => {
          const r = await Noodl.Records.query(c, where, { limit: 1000, plain: true });
          if (r.length >= 1000) throw new Error(c + ' returned a full page; refusing to treat it as everything');
          return r;
        };
        for (const p of PLAN) {
          if (p.by) {
            rows[p.c] = await q(p.c, { [p.by]: { equalTo: learnerId } });
          } else {
            const ids = (rows[p.via] || []).map((r) => r[p.key]).filter((x) => x !== undefined && x !== null && x !== '');
            rows[p.c] = ids.length ? await q(p.c, { [p.key]: { containedIn: ids } }) : [];
          }
        }
      }
      const alsoDeleted = {};
      if (learnerId) {
        for (const p of ALSO_DELETED) {
          const r = await Noodl.Records.query(p.c, { [p.by]: { equalTo: learnerId } }, { limit: 1000, plain: true });
          if (r.length >= 1000) throw new Error(p.c + ' returned a full page; refusing to treat it as everything');
          alsoDeleted[p.c] = r;
        }
      }
      Outputs.rows = rows;
      Outputs.alsoDeleted = alsoDeleted;
      Outputs.order = deletionOrder();
      Outputs.done();
    } catch (e) {
      Outputs.error = String((e && e.message) || e);
      console.error('[dbt:Rows about] ' + Outputs.error + ' learner=' + String(Inputs.learnerId || '-'));
      Outputs.failed();
    }
  })();
}
